# filename: check_directory.py
import os
from pathlib import Path

print("Checking current directory for SQL files or documentation...")
current_dir = Path.cwd()

# Look for SQL files
sql_files = list(current_dir.glob('*.sql'))
print(f"\nSQL files found: {len(sql_files)}")
for sql_file in sql_files:
    print(f"  - {sql_file.name}")
    # Check if file contains references to our table
    try:
        with open(sql_file, 'r') as f:
            content = f.read()
            if 'lever__hiring_manager_scorecard' in content:
                print(f"    Contains reference to 'lever__hiring_manager_scorecard'")
    except Exception as e:
        print(f"    Error reading file: {e}")

# Look for documentation files
doc_extensions = ['.md', '.txt', '.rst', '.yaml', '.yml', '.json']
for ext in doc_extensions:
    doc_files = list(current_dir.glob(f'*{ext}'))
    for doc_file in doc_files:
        print(f"  - {doc_file.name}")
        try:
            with open(doc_file, 'r') as f:
                content = f.read()
                if 'lever__hiring_manager_scorecard' in content:
                    print(f"    Contains reference to 'lever__hiring_manager_scorecard'")
        except Exception as e:
            pass

# List all files for context
print("\nAll files in current directory:")
for item in current_dir.iterdir():
    if item.is_file():
        print(f"  - {item.name}")
